const csv = $json.data ?? $json.body ?? $json;
const texto = (typeof csv === 'string') ? csv : JSON.stringify(csv);

const linhas = texto.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = linhas[0].split(',').map(h => h.trim());

const investimentos = linhas.slice(1).map(linha => {
  const cols = linha.split(',').map(c => c.trim());
  const obj = {};

  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

  // normaliza mínimo para número
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

  return obj;
});

return [{ json: { investimentos } }];

// Recebe os dados dos investidores do Webhook
const webhook = $('Webhook').first().json;
const clientes = webhook.body.clientes;

// Recupera os investimentos do Merge
const entrada = $input.all();

let investimentos = [];

for (const item of entrada) {
  if (Array.isArray(item.json.investimentos)) {
    investimentos = item.json.investimentos;
    break;
  }
}

// Gera uma resposta para cada investidor
const resultados = clientes.map(cliente => {

  const nome = String(cliente.nome ?? '').trim();
  const email = String(cliente.email ?? '').trim();
  const perfil = String(cliente.perfil ?? '').trim();
  const saldoTexto = String(cliente.saldo ?? '').trim();

  // Converte o saldo para número
  const saldo = Number(
    saldoTexto
      .replace(/[R$\s]/g, '')
      .replace(/\./g, '')
      .replace(',', '.')
  ) || 0;

  // Busca investimentos compatíveis com perfil e saldo
  const opcoes = investimentos.filter(inv =>
    String(inv.perfil).toLowerCase() === perfil.toLowerCase() &&
    Number(inv.minimo) <= saldo
  );

  // Escolhe o investimento de maior valor mínimo possível
  opcoes.sort((a, b) => Number(b.minimo) - Number(a.minimo));

  const investimento = opcoes[0];

  const recomendacao = investimento
    ? investimento.produto
    : 'Nenhum investimento compatível encontrado';

  const motivo = investimento
    ? `Perfil ${perfil}. Investimento mínimo de R$ ${Number(investimento.minimo).toLocaleString('pt-BR')}. Rentabilidade informada: ${investimento.rentabilidade}.`
    : 'Não encontramos uma opção compatível com o perfil e saldo informados.';

  const mensagem = `
Olá, ${nome}!

Analisamos seus dados e preparamos uma sugestão de investimento.

Nome: ${nome}
E-mail: ${email}
Perfil: ${perfil}
Saldo disponível: ${saldoTexto}

Investimento recomendado: ${recomendacao}

Motivo:
${motivo}

Importante: rentabilidade não é garantia de retorno. Avalie os riscos antes de investir.

Atenciosamente,
Equipe de Investimentos
`.trim();

  return {
    json: {
      nome,
      email,
      perfil,
      saldo: saldoTexto,
      recomendacao,
      motivo,
      assunto: 'Sua recomendação personalizada de investimentos',
      mensagem
    }
  };
});

return resultados;

// Recebe os dados do Code in JavaScript1
const entrada = $input.all();

// Define as colunas do CSV
const cabecalho = [
  'email',
  'nome',
  'perfil',
  'saldo_texto',
  'saldo_numero',
  'recomendacao'
];

// Escapa valores para evitar erros no CSV
function escaparCSV(valor) {
  const texto = String(valor ?? '');
  return '"' + texto.replace(/"/g, '""') + '"';
}

// Cria o cabeçalho
const linhas = [cabecalho.join(',')];

// Cria uma linha para cada investidor
for (const item of entrada) {
  const c = item.json;

  // Converte o saldo brasileiro para número
  const saldoTexto = String(c.saldo_texto ?? c.saldo ?? '');
  const saldoNumero = Number(
    saldoTexto
      .replace(/[R$\s]/g, '')
      .replace(/\./g, '')
      .replace(',', '.')
  ) || 0;

  const valores = [
    c.email,
    c.nome,
    c.perfil,
    saldoTexto,
    saldoNumero,
    c.recomendacao
  ];

  linhas.push(valores.map(escaparCSV).join(','));
}

// Monta o conteúdo CSV
const csv = '\uFEFF' + linhas.join('\r\n');

// Retorna o CSV
return [
  {
    json: {
      arquivo: 'investidores.csv',
      contentType: 'text/csv; charset=utf-8',
      csv
    }
  }
];
